17	namespace hybrid {
18	
19	struct DmiBus
20	{
21	  virtual ~DmiBus() = default;
22	  virtual void write(uint8_t reg, uint32_t value) = 0;
23	  virtual auto read(uint8_t reg) -> uint32_t = 0;
24	};
25	
26	inline auto read_register_64(DmiBus& bus, uint16_t regno,
27	                             const char* poll_label) -> uint64_t;
28	
29	class ResumeDriver
30	{
31	public:
32	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
33	  // dmcontrol/dmstatus are run-control registers specific to this driver.
34	  static constexpr uint8_t kData0      = kDmiData0;
35	  static constexpr uint8_t kData1      = kDmiData1;
36	  static constexpr uint8_t kDmcontrol  = 0x10;
37	  static constexpr uint8_t kDmstatus   = 0x11;
38	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
39	  static constexpr uint8_t kCommand    = kDmiCommand;
40	
41	  static constexpr uint16_t kCsrDpc      = 0x7B1;
42	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
43	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
44	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
45	  static constexpr uint16_t kCsrFcsr     = 0x003;
46	  static constexpr uint16_t kCsrMstatus  = 0x300;
47	  static constexpr uint16_t kCsrMisa     = 0x301;
48	  static constexpr uint16_t kCsrMedeleg  = 0x302;
49	  static constexpr uint16_t kCsrMideleg  = 0x303;
50	  static constexpr uint16_t kCsrMie      = 0x304;
51	  static constexpr uint16_t kCsrMtvec    = 0x305;
52	  static constexpr uint16_t kCsrMscratch = 0x340;
53	  static constexpr uint16_t kCsrMepc     = 0x341;
54	  static constexpr uint16_t kCsrMcause   = 0x342;
55	  static constexpr uint16_t kCsrMtval    = 0x343;
56	  static constexpr uint16_t kCsrMip      = 0x344;
57	  static constexpr uint16_t kCsrSatp     = 0x180;
58	  static constexpr uint16_t kCsrMcycle   = 0xB00;
59	  static constexpr uint16_t kCsrMinstret = 0xB02;
60	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
61	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
62	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
63	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
64	  static constexpr uint16_t kCsrVlenb    = 0xC22;
65	  static constexpr uint16_t kCsrVstart   = 0x008;
66	  static constexpr uint16_t kCsrVxsat    = 0x009;
67	  static constexpr uint16_t kCsrVxrm     = 0x00A;
68	  static constexpr uint16_t kCsrVcsr     = 0x00F;
69	  static constexpr uint16_t kCsrVtype    = 0xC21;
70	  static constexpr uint16_t kCsrVl       = 0xC20;
71	
72	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
73	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
74	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
75	
76	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
77	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
78	
79	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
80	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
81	
82	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
83	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
84	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
85	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
86	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
87	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
88	
89	  static constexpr unsigned kPollIterations = kDmiPollIterations;
90	
91	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
92	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
93	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
94	  // GPA still unset throws in the sweep (no silent transport via a bogus
95	  // address). The simulator passes the real value from platform.main_memory.
96	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
97	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
98	  // every CSR, the prior behavior -- so existing call sites are unchanged.
99	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
100	                        AndesCaps caps = AndesCaps::all())
101	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
102	  {}
103	
104	  // Opt-in GPR block-load (prototype): reload x1..x31 with a Program-Buffer
105	  // ld-sweep from the scratch page instead of 31 abstract register writes.
106	  // Off by default so existing callers/tests are unchanged; the simulator
107	  // enables it and stages the values via stage_gpr_to_scratch.
108	  void set_gpr_block_load(bool on) { gpr_block_load_ = on; }
109	
110	  // Opt-in FPR block-load (prototype): reload f0..f31 with a Program-Buffer
111	  // fld-sweep from the scratch page instead of 32 abstract register writes.
112	  // Off by default so existing callers/tests are unchanged; the simulator
113	  // enables it and stages the values via stage_fpr_to_scratch.
114	  void set_fpr_block_load(bool on) { fpr_block_load_ = on; }
115	
116	  // Opt-in Andes+M-ext CSR sweep: restore the caps-supported CSR block with a
117	  // Program-Buffer ld+csrrw sweep from the CSR scratch page instead of one
118	  // abstract write per CSR. Off by default; the simulator enables it and stages
119	  // the values via stage_csr_to_scratch. Shares the flag name with StateDrain.
120	  void set_csr_sweep(bool on) { csr_sweep_ = on; }
121	
122	  // LG1/LG2 (liveness gate): supply the engine's own reset-state drain.
123	  // Restores whose drained value equals this baseline are skipped -- the
124	  // write would be a no-op, and every DM operation costs hundreds of
125	  // simulated cycles. LG1 gates each tolerant CSR write; LG2 elides the FPR
126	  // and V data blocks as whole blocks when byte-equal. Unset (default) keeps
127	  // transport-everything. Always-live state (mstatus, GPRs, dpc, dcsr,
128	  // mcycle, minstret, the S/U PMP mirror) is never gated.
129	  //
130	  // v_cfg_at_reset: pass false when the baseline was CAPTURED this run --
131	  // the capture drain's V dump sweep already clobbered the hart's
132	  // vtype/vl/vstart, so their baseline equality no longer proves the
133	  // architectural vsetvl redundant. Cache-hit runs (pristine hart) pass true.
134	  void set_reset_baseline(const hybrid_state_v1& b, bool v_cfg_at_reset = true)
135	  {
136	    baseline_ = b;
137	    has_baseline_ = true;
138	    v_cfg_at_reset_ = v_cfg_at_reset;
139	  }
140	
141	  // Number of register-restore operations elided by the reset baseline this
142	  // resume: one per gated CSR write, 32 per elided FPR/V data block, one per
143	  // elided vsetvl.
144	  auto baseline_skip_count() const -> uint64_t { return baseline_skip_count_; }
145	
146	  void resume(const hybrid_state_v1& state)
147	  {
148	    if (state.magic != HYBRID_STATE_MAGIC)
149	      throw std::runtime_error("ResumeDriver::resume: bad magic");
150	    if (state.version != HYBRID_STATE_VERSION)
151	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
152	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
153	    if (state.priv == 2 || state.priv > 3)
154	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
155	
156	    // dmactive must transition 0->1 in its own write before any other
157	    // DMCONTROL bit is honored (RISC-V Debug Spec).
158	    bus_.write(kDmcontrol, kDmcontrolDmactive);
159	    request_halt();
160	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
161	
162	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
163	    // accepted (FS or VS == Off disables the extension and the hart NACKs
164	    // the writes). The drained state.mstatus may legitimately carry FS or
165	    // VS at Off (e.g. an OS context-switched the regs away before the
166	    // trigger fired) -- gating the write on the drained field skips the
167	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
168	    // write mstatus when either extension is in scope; force-OR Initial
169	    // when the drained field is Off. This enable is local to the vsim
170	    // phase; the state.mstatus written to the handoff file is left
171	    // unmodified.
172	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
173	      uint64_t enable_mstatus = state.mstatus;
174	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
175	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
176	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
177	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
178	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
179	    }
180	
181	    // FPR restore (requires mstatus.FS enabled above). The block-load (opt-in)
182	    // sweeps f0..f31 from the scratch page via a PB fld-sweep -- ~6 halted-hart
183	    // round-trips instead of 32 abstract writes -- when the V region leaves room;
184	    // otherwise fall back to per-register abstract writes. Its integer base x5 is
185	    // re-staged by the V sweep and restored by the GPR loop below, so it is safe
186	    // to clobber here.
187	    if (state.flags & HYBRID_FLAG_FP) {
188	      // LG2: elide the whole FPR block when every f-reg already holds the
189	      // engine's reset value -- the reload would rewrite what is there.
190	      const bool fpr_equal = has_baseline_
191	        && std::memcmp(state.fpr, baseline_.fpr, sizeof state.fpr) == 0;
192	      if (fpr_equal) {
193	        baseline_skip_count_ += 32;
194	      } else if (fpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
195	                 && fpr_scratch_fits(state.vlenb)) {
196	        restore_fprs_via_pb(fpr_scratch_gpa(scratch_gpa_));
197	      } else {
198	        for (uint16_t i = 0; i < 32; ++i)
199	          write_64bit_register(regno_fpr(i), state.fpr[i]);
200	      }
201	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
202	      // fallback scratch x5 is overwritten by the GPR loop below.
203	      if (!baseline_skips(state.fcsr, baseline_.fcsr))
204	        write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
205	    }
206	
207	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
208	    // the GPR loop overwrites x5 afterward so state is preserved).
209	    if (state.flags & HYBRID_FLAG_V) {
210	      // V data regfile: reload v0..v31 from the shared scratch region via the
211	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
212	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
213	      // the restore then overwrites with the architectural values. The sweep
214	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
215	      // below restores all three. The scratch is vlenb-packed
216	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
217	      if (scratch_gpa_ == kVScratchGpaUnset)
218	        throw std::runtime_error(
219	          "ResumeDriver::resume: V state present but scratch GPA unset");
220	      // LG2: elide the reload sweep when every v-reg already holds the
221	      // engine's reset bytes.
222	      const bool v_data_equal = has_baseline_
223	        && std::memcmp(state.vreg, baseline_.vreg, sizeof state.vreg) == 0;
224	      if (v_data_equal)
225	        baseline_skip_count_ += 32;
226	      else
227	        pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
228	
229	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
230	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
231	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
232	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
233	      // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
234	      // vstart, so baseline equality only proves this vsetvl redundant when
235	      // the sweep did NOT run.
236	      const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
237	        && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
238	      if (vcfg_equal) {
239	        ++baseline_skip_count_;  // the elided vsetvl exec
240	      } else {
241	        write_64bit_register(regno_gpr(5), state.vl);
242	        write_64bit_register(regno_gpr(6), state.vtype);
243	        const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
244	        exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
245	      }
246	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
247	      // baseline skip is likewise only valid when no vsetvl executed.
248	      if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
249	        write_csr_abstract_or_pb(kCsrVstart, state.vstart);
250	      if (!baseline_skips(state.vxsat, baseline_.vxsat))
251	        write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
252	      if (!baseline_skips(state.vxrm, baseline_.vxrm))
253	        write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
254	      if (!baseline_skips(state.vcsr, baseline_.vcsr))
255	        write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
256	    }
257	
258	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
259	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
260	    // in the drained privilege; M-mode states skip the write (prv already 3).
261	    // Before the GPR loop: a PB fallback would clobber scratch x5.
262	    if (state.priv != 3) {
263	      // L2 slice: with PMP implemented and no matching entry, every S/U
264	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
265	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
266	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
267	      // RV64. Tolerant writes: entries beyond what the hart implements
268	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
269	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
270	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
271	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
272	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
273	
274	      const uint64_t dcsr =
275	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
276	      write_csr_abstract_or_pb(kCsrDcsr,
277	                               (dcsr & ~uint64_t{0x3}) | state.priv);
278	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
279	      // silently measure the ROI in the wrong privilege. Verify and abort.
280	      const uint64_t got =
281	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
282	        & 0x3u;
283	      if (got != state.priv)
284	        throw std::runtime_error(
285	          "ResumeDriver::resume: engine does not implement privilege level "
286	          + std::to_string(state.priv)
287	          + " (dcsr.prv pinned to " + std::to_string(got)
288	          + "); pick an S/U-capable engine");
289	    }
290	
291	    // Andes V5 + M-ext CSR restore. Runs BEFORE the GPR loop so the csr_sweep
292	    // may use x5/x6 as scratch (the GPR loop restores them after, exactly like
293	    // the FPR and V restores above). See restore_andes_m_ext.
294	    restore_andes_m_ext(state);
295	
296	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
297	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
298	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
299	    // region leaves room; otherwise fall back to per-register abstract writes.
300	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
301	        && gpr_scratch_fits(state.vlenb)) {
302	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
303	    } else {
304	      for (uint16_t i = 1; i < 32; ++i)
305	        write_64bit_register(regno_gpr(i), state.gpr[i]);
306	    }
307	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
308	
309	    write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
310	
311	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
312	    // register with no hardware side effects, legal to use inside a trap-free
313	    // ROI. Restore it so a value stashed before the handoff survives into the
314	    // vsim phase.
315	    write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
316	
317	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
318	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
319	    // value stashed before the handoff must survive into the vsim phase (same
320	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
321	    // hardware-driven pending bits, or mtval on a core that hardwires it)
322	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
323	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
324	    write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
325	    write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
326	    write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
327	    write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
328	    write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
329	
330	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
331	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
332	    // caches) but has no cache model, so without this the cycle engine resumes
333	    // at the ROI with caches at their reset default -- DISABLED -- and the
334	    // whole measured window runs uncached, inflating it severalfold. Tolerant
335	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
336	    // write as a no-op, and a drained 0 (caches were off) restores the reset
337	    // state, so this is always safe to issue.
338	    write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
339	                             baseline_.mcache_ctl);
340	    write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
341	                             baseline_.mmisc_ctl);
342	
343	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
344	    // from QEMU1's drain value. Without this, vsim's local counter starts
345	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
346	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
347	    // overwrite here as the GPR loop already ran.
348	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
349	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
350	
351	    clear_cmderr_if_set();
352	    request_resume();
353	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
354	                   "ResumeDriver resume");
355	  }
356	
357	private:
358	  void request_halt()
359	  {
360	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
361	  }
362	
363	  void request_resume()
364	  {
365	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
366	  }
367	
368	  void write_64bit_register(uint16_t regno, uint64_t value)
369	  {
370	    write_register_abstract(bus_, regno, value);
371	  }
372	
373	  // GPR block-load: reload x1..x31 from the scratch page via a PB ld-sweep. Base
374	  // x31 rides the sweep last (it is the base pointer). x31's slot is the
375	  // mapping's final word, which the memory decoder now returns correctly.
376	  void restore_gprs_via_pb(uint64_t gpr_gpa)
377	  {
378	    pb_block_sweep(bus_, 31, gpr_gpa, 1, 32, &encode_ld);
379	  }
380	
381	  // FPR block-load: reload f0..f31 from the scratch page via a PB fld-sweep,
382	  // integer base x5 (a caller-saved scratch the GPR loop restores later). No
383	  // f-reg is the base, so all 32 ride the sweep (first_reg = 0).
384	  void restore_fprs_via_pb(uint64_t fpr_gpa)
385	  {
386	    pb_block_sweep(bus_, 5, fpr_gpa, 0, 32, &encode_fld);
387	  }
388	
389	  // Andes V5 + M-ext CSR restore. When the sweep is enabled and the V region
390	  // leaves room, batch every caps-supported CSR from the CSR scratch page via a
391	  // Program-Buffer ld+csrrw sweep (~3 CSRs per DM round-trip; base x6 / value x5,
392	  // both restored by the GPR loop that runs after). Else fall back to one
393	  // caps-gated abstract write per CSR. The scratch was packed in
394	  // for_each_sweep_csr order by stage_csr_to_scratch, so the sweep's addr list
395	  // uses that same walk. Absent CSRs are never in the list (caps-gated), so no
396	  // csrrw faults -- a fault would mean the caps map is wrong (a config bug).
397	  void restore_andes_m_ext(const hybrid_state_v1& state)
398	  {
399	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
400	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
401	    if (!andes && !mext) return;
402	
403	    // NOTE: the sweep transports the full caps-supported list -- it does NOT
404	    // honor the reset baseline (LG1). Filter `addrs` by baseline_skips before
405	    // ever enabling the sweep together with a baseline.
406	    if (csr_sweep_ && scratch_gpa_ != kVScratchGpaUnset
407	        && csr_scratch_fits(state.vlenb)) {
408	      std::array<uint16_t, kCsrScratchSlots> addrs{};
409	      std::size_t n = 0;
410	      for_each_sweep_csr(state, caps_,
411	        [&](std::size_t i, uint16_t addr, const uint64_t&) {
412	          addrs[i] = addr; n = i + 1;
413	        });
414	      csr_sweep(bus_, /*base=*/6, csr_scratch_gpa(scratch_gpa_), /*val=*/5,
415	                std::span<const uint16_t>{addrs.data(), n}, CsrSweepDir::Restore);
416	      return;
417	    }
418	
419	    // Fallback: one caps-gated abstract write per CSR (pmaaddr before pmacfg,
420	    // mirroring the PMP restore ordering).
421	    if (andes) {
422	#define X(field, addr, name)     \
423	  if (caps_.supports_csr(addr))  \
424	    write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
425	      HYBRID_ANDES_CSR_LIST(X)
426	#undef X
427	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
428	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
429	          write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
430	                                   state.andes.pmaaddr[i],
431	                                   baseline_.andes.pmaaddr[i]);
432	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
433	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
434	          write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
435	                                   state.andes.pmacfg[i],
436	                                   baseline_.andes.pmacfg[i]);
437	    }
438	    if (mext) {
439	#define X(field, addr, name)     \
440	  if (caps_.supports_csr(addr))  \
441	    write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
442	      HYBRID_M_EXT_CSR_LIST(X)
443	#undef X
444	    }
445	  }
446	
447	  // Abstract-first CSR write with Program Buffer fallback.
448	  // Tries an abstract register write; if the DM signals cmderr, clears it,
449	  // stages the value in scratch_gpr via abstract GPR write, then executes a
450	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
451	  // to x5 (t0) which the GPR restore loop overwrites later.
452	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
453	                                 uint8_t scratch_gpr = 5)
454	  {
455	    write_64bit_register(regno_csr(csr), value);
456	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
457	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
458	    write_64bit_register(regno_gpr(scratch_gpr), value);
459	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
460	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
461	  }
462	
463	  // Write a CSR-addressable register and clear any cmderr the DM raised.
464	  // Used for CSRs whose abstract-access support may be implementation
465	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
466	  // remaining writes.
467	  void write_csr_tolerant(uint16_t csr, uint64_t value)
468	  {
469	    write_64bit_register(regno_csr(csr), value);
470	    clear_cmderr_if_set();
471	  }
472	
473	  // LG1: true (and counted) when the reset baseline marks this write a no-op.
474	  auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
475	  {
476	    if (!has_baseline_ || value != reset_value) return false;
477	    ++baseline_skip_count_;
478	    return true;
479	  }
480	
481	  // Tolerant CSR write elided when the value already equals the engine's
482	  // reset value (reset_value is only meaningful when the baseline is set;
483	  // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
484	  void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
485	                                uint64_t reset_value)
486	  {
487	    if (baseline_skips(value, reset_value)) return;
488	    write_csr_tolerant(csr, value);
489	  }
490	
491	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
492	  // is rejected until the bits are W1C-cleared. We tolerate per-register
493	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
494	  // error before resuming so the hart isn't left in a stuck state.
495	  // B17: record the last observed non-zero cmderr and a clear count so a
496	  // partially-broken restore is observable via the public accessors
497	  // instead of silently swallowed.
498	  void clear_cmderr_if_set()
499	  {
500	    const auto status = bus_.read(kAbstractcs);
501	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
502	    if (code != 0u) {
503	      last_observed_cmderr_ = code;
504	      ++cmderr_clear_count_;
505	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
506	    }
507	  }
508	
509	  DmiBus& bus_;
510	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
511	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
512	  bool gpr_block_load_ = false;               // opt-in GPR PB ld-sweep
513	  bool fpr_block_load_ = false;               // opt-in FPR PB fld-sweep
514	  bool csr_sweep_      = false;               // opt-in Andes+M-ext PB csr sweep
515	  hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
516	  bool has_baseline_ = false;                 // baseline_ valid only when set
517	  bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
518	  uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
519	  uint32_t last_observed_cmderr_ = 0;
520	  uint64_t cmderr_clear_count_   = 0;
521	
522	public:
523	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
524	  // at least one abstract write tripped a sticky cmderr the restore
525	  // tolerated by clearing. cmderr_clear_count() is the total number of
526	  // such clears across all calls into clear_cmderr_if_set() this run.
527	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
528	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
529	};
530	
531	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
532	// via an Abstract Command. Halts-and-reads contract: caller must have the
533	// hart in the halted state. Shared by StateDrain (drain at exit). If
534	// abstractcs.cmderr goes sticky after the command, the helper clears it and
535	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
536	// instead of corrupting the adjacent field.
537	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
538	                                     const char* poll_label
539	                                       = "read_register_64")
540	  -> std::optional<uint64_t>
541	{
542	  using RD = ResumeDriver;
543	  bus.write(RD::kCommand,
544	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
545	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
546	  const auto status = bus.read(RD::kAbstractcs);
547	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
548	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
549	    return std::nullopt;
550	  }
551	  const uint64_t lo = bus.read(RD::kData0);
552	  const uint64_t hi = bus.read(RD::kData1);
553	  return lo | (hi << 32);
554	}
555	
556	inline auto read_register_64(DmiBus& bus, uint16_t regno,
557	                             const char* poll_label = "read_register_64")
558	  -> uint64_t
559	{
560	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
561	}
562	
563	}  // namespace hybrid
