TEST_CASE("v4 csr_sweep: resume restores Andes+M-ext via a PB ld+csrrw sweep, "
          "base x6 seeded, no per-CSR abstract writes")
{
  RecordingBus bus;
  bus.dmstatus_value   = (1u << 9) | (1u << 17);
  bus.abstractcs_value = 8u << 24;  // progbufsize=8 -> 3 CSRs/exec

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  s.vlenb = 0;  // csr_scratch_fits
  uint64_t v = 0xA00000000ULL;
#define X(field, addr, name) s.andes.field = v++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
#define X(field, addr, name) s.m_ext.field = v++;
  HYBRID_M_EXT_CSR_LIST(X)
#undef X

  hybrid::ResumeDriver driver(bus, kScratch);  // caps default all()
  driver.set_csr_sweep(true);
  driver.resume(s);

  // Expected supported addr list, canonical order (single source of truth).
  std::vector<uint16_t> addrs;
  hybrid::for_each_sweep_csr(s, hybrid::AndesCaps::all(),
    [&](std::size_t, uint16_t addr, const uint64_t&) { addrs.push_back(addr); });
  REQUIRE(!addrs.empty());

  auto progbuf_has = [&](uint32_t insn) {
    for (const auto& op : bus.ops)
      if (op.kind == DmiOp::Kind::Write && op.reg >= hybrid::kProgbuf0
          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
          && op.value == insn) return true;
    return false;
  };
  // (a) each supported CSR: ld from its scratch slot + csrrw to the CSR.
  for (std::size_t k = 0; k < addrs.size(); ++k) {
    CHECK(progbuf_has(hybrid::encode_ld(5, 6, int32_t(k * 8))));
    CHECK(progbuf_has(hybrid::encode_csrrw(0, addrs[k], 5)));
  }
  // (b) base pointer x6 seeded with the CSR scratch GPA (staged in DATA0 before
  // the FIRST abstract write to x6 -- the seed runs before the GPR loop).
  std::optional<uint32_t> seed_data0;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_gpr(6)
        && ((op.value >> 16) & 1u)) {
      if (bus.ops[i - 2].reg == kData0) seed_data0 = bus.ops[i - 2].value;
      break;
    }
  }
  REQUIRE(seed_data0.has_value());
  CHECK(*seed_data0 == uint32_t(hybrid::csr_scratch_gpa(kScratch) & 0xFFFFFFFFu));
  // (c) NO per-CSR abstract write-COMMAND to a swept CSR -- they rode the sweep.
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    if (!((op.value >> 16) & 1u)) continue;  // writes only
    const uint16_t regno = op.value & 0xFFFFu;
    for (uint16_t a : addrs)
      CHECK(regno != hybrid::regno_csr(a));
  }
}

TEST_CASE("LG1: reset-baseline gating skips tolerant CSR writes whose drained "
          "value equals the engine reset value, still restores differing ones")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  uint64_t v = 0xA00000000ULL;
#define X(field, addr, name) s.andes.field = v++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
#define X(field, addr, name) s.m_ext.field = v++;
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i) s.andes.pmaaddr[i] = 0xD000 + i;
  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)  s.andes.pmacfg[i]  = 0xC0 + i;
  s.mtvec = 0x2000; s.mscratch = 0x31; s.mepc = 0x11; s.mcause = 0x2;
  s.mtval = 0x9; s.mie = 0x888; s.mip = 0x80; s.mcache_ctl = 0x3;
  s.mmisc_ctl = 0x48;

  // Baseline = the engine's own reset-state drain. Equal everywhere EXCEPT
  // uitb and mcache_ctl (the program wrote those before the handoff), so
  // only those two writes still change hart state.
  hybrid_state_v1 baseline = s;
  s.andes.uitb = 0xBEEF0;
  s.mcache_ctl = 0x10003;

  hybrid::ResumeDriver driver(bus, kScratch);  // caps default all()
  driver.set_reset_baseline(baseline);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  // Differing values must still be restored.
  CHECK(contains_regno(ns, hybrid::regno_csr(0x800)));   // uitb
  CHECK(contains_regno(ns, hybrid::regno_csr(0x7CA)));   // mcache_ctl
  // Values already equal to the engine reset value: the write is a no-op,
  // each elided abstract command saves hundreds of simulated cycles.
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x7C4)));  // mxstatus (Andes)
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x30A)));  // menvcfg (M-ext)
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0xBD0)));  // pmaaddr0
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0xBC0)));  // pmacfg0
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x341)));  // mepc
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x305)));  // mtvec

  // Skip count = every gated write except the two that differed.
  std::size_t total = 9;  // mtvec mscratch mepc mcause mtval mie mip
                          // mcache_ctl mmisc_ctl
#define X(field, addr, name) ++total;
  HYBRID_ANDES_CSR_LIST(X)
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
  total += HYBRID_PMA_ADDR_NUM + HYBRID_PMA_CFG_NUM;
  CHECK(driver.baseline_skip_count() == total - 2);
}

TEST_CASE("LG1: always-live state (GPRs, dpc, mcycle, minstret) is restored "
          "even when it equals the baseline; no baseline -> nothing skipped")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, /*x10=*/0xdeadbeef);
  s.mcycle = 77;
  s.minstret = 33;

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_reset_baseline(s);  // baseline identical to the state
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  CHECK(contains_regno(ns, hybrid::regno_gpr(10)));
  CHECK(contains_regno(ns, hybrid::regno_csr(0x7B1)));  // dpc
  CHECK(contains_regno(ns, hybrid::regno_csr(0xB00)));  // mcycle
  CHECK(contains_regno(ns, hybrid::regno_csr(0xB02)));  // minstret
  // Only the 9 tolerant base scalars were gated (no Andes/M-ext flags here).
  CHECK(driver.baseline_skip_count() == 9);

  // Without a baseline the transport-everything behavior is unchanged.
  RecordingBus bus2;
  bus2.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver plain(bus2, kScratch);
  plain.resume(s);
  CHECK(plain.baseline_skip_count() == 0);
  CHECK(contains_regno(cmd_regnos(bus2.ops), hybrid::regno_csr(0x341)));  // mepc
}

TEST_CASE("LG2: baseline-equal FPR block skips the per-register abstract "
          "writes, the fld sweep, and the fcsr write")
{
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xF00 + i;
  s.fcsr = 0xA1;
  const hybrid_state_v1 baseline = s;

  // (a) abstract path (block-load off): no FPR regno, no fcsr command.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_reset_baseline(baseline);
  driver.resume(s);
  const auto ns = cmd_regnos(bus.ops);
  for (int i = 0; i < 32; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(i)));
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x003)));  // fcsr
  // 32 FPRs + fcsr + the 9 tolerant base scalars (all zero == baseline).
  CHECK(driver.baseline_skip_count() == 32u + 1u + 9u);

  // (b) block-load path: the fld sweep was the only Program-Buffer user in
  // this state, so NO PB execution may fire at all.
  RecordingBus bus2;
  bus2.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver d2(bus2, kScratch);
  d2.set_fpr_block_load(true);
  d2.set_reset_baseline(baseline);
  d2.resume(s);
  for (const auto& op : bus2.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == kCommand
                 && op.value == hybrid::kExecProgbufCmd));

  // (c) ONE differing register defeats the whole-block gate.
  RecordingBus bus3;
  bus3.dmstatus_value = (1u << 9) | (1u << 17);
  auto s3 = s;
  s3.fpr[3] ^= 1;
  hybrid::ResumeDriver d3(bus3, kScratch);
  d3.set_reset_baseline(baseline);
  d3.resume(s3);
  CHECK(contains_regno(cmd_regnos(bus3.ops), hybrid::regno_fpr(3)));
}

