TEST_CASE("v_regfile_xfer: kCsrScratchBytes covers all Andes+PMA+M-ext CSRs")
{
  // 13 Andes scalars + 2 pmacfg + 16 pmaaddr + 51 M-ext = 82 slots.
  CHECK(hybrid::kCsrScratchSlots == 82u);
  CHECK(hybrid::kCsrScratchBytes == 82u * 8u);
  // The CSR region sits below the FPR block; V must clear all three.
  CHECK(hybrid::csr_scratch_gpa(0x1000)
        == 0x1000 + hybrid::kVScratchBytes - hybrid::kGprScratchBytes
             - hybrid::kFprScratchBytes - hybrid::kCsrScratchBytes);
  CHECK(hybrid::csr_scratch_fits(64));    // 2048 <= 2936
  CHECK(!hybrid::csr_scratch_fits(96));   // 3072 >  2936
}

TEST_CASE("v_regfile_xfer: stage_csr/read_csr roundtrip Andes+M-ext in canonical "
          "order (caps=all)")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  uint64_t v = 0xC500000000ULL;
#define X(field, addr, name) in.andes.field = v++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  for (int p = 0; p < HYBRID_PMA_CFG_NUM; ++p)  in.andes.pmacfg[p]  = v++;
  for (int p = 0; p < HYBRID_PMA_ADDR_NUM; ++p) in.andes.pmaaddr[p] = v++;
#define X(field, addr, name) in.m_ext.field = v++;
  HYBRID_M_EXT_CSR_LIST(X)
#undef X

  std::vector<uint8_t> ram(static_cast<size_t>(128) * 1024 * 1024);
  hybrid::stage_csr_to_scratch(in, ram, hybrid::AndesCaps::all());

  hybrid_state_v1 out{};
  out.flags = in.flags;  // the lift gate reads the flags
  hybrid::read_csr_from_scratch(out, ram, hybrid::AndesCaps::all());

#define X(field, addr, name) CHECK(out.andes.field == in.andes.field);
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  for (int p = 0; p < HYBRID_PMA_CFG_NUM; ++p)  CHECK(out.andes.pmacfg[p]  == in.andes.pmacfg[p]);
  for (int p = 0; p < HYBRID_PMA_ADDR_NUM; ++p) CHECK(out.andes.pmaaddr[p] == in.andes.pmaaddr[p]);
#define X(field, addr, name) CHECK(out.m_ext.field == in.m_ext.field);
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
}

