{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_M_EXT;  // no ANDES
  in.andes.mxstatus = 0xAAAA;  // must NOT be staged
  in.m_ext.menvcfg  = 0xBBBB;  // must be staged

  std::vector<uint8_t> ram(static_cast<size_t>(128) * 1024 * 1024);
  hybrid::stage_csr_to_scratch(in, ram, hybrid::AndesCaps::all());

  hybrid_state_v1 out{};
  out.flags = in.flags;
  out.andes.mxstatus = 0x1234;  // sentinel; must survive
  hybrid::read_csr_from_scratch(out, ram, hybrid::AndesCaps::all());

  CHECK(out.m_ext.menvcfg  == 0xBBBBu);  // M-ext lifted
  CHECK(out.andes.mxstatus == 0x1234u);  // Andes block skipped -> sentinel intact
}

