TEST_CASE("v4 csr_sweep: resume restores Andes+M-ext via a PB ld+csrrw sweep, "
          "base x6 seeded, no per-CSR abstract writes")
{
  RecordingBus bus;
  bus.dmstatus_value   = (1u << 9) | (1u << 17);
  bus.abstractcs_value = 8u << 24;  // progbufsize=8 -> 3 CSRs/exec

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  s.vlenb = 0;  // csr_scratch_fits
  uint64_t v = 0xA00000000ULL;
#define X(field, addr, name) s.andes.field = v++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
#define X(field, addr, name) s.m_ext.field = v++;
  HYBRID_M_EXT_CSR_LIST(X)
#undef X

  hybrid::ResumeDriver driver(bus, kScratch);  // caps default all()
  driver.set_csr_sweep(true);
  driver.resume(s);

  // Expected supported addr list, canonical order (single source of truth).
  std::vector<uint16_t> addrs;
  hybrid::for_each_sweep_csr(s, hybrid::AndesCaps::all(),
    [&](std::size_t, uint16_t addr, const uint64_t&) { addrs.push_back(addr); });
  REQUIRE(!addrs.empty());

  auto progbuf_has = [&](uint32_t insn) {
    for (const auto& op : bus.ops)
      if (op.kind == DmiOp::Kind::Write && op.reg >= hybrid::kProgbuf0
          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
          && op.value == insn) return true;
    return false;
  };
  // (a) each supported CSR: ld from its scratch slot + csrrw to the CSR.
  for (std::size_t k = 0; k < addrs.size(); ++k) {
    CHECK(progbuf_has(hybrid::encode_ld(5, 6, int32_t(k * 8))));
    CHECK(progbuf_has(hybrid::encode_csrrw(0, addrs[k], 5)));
  }
  // (b) base pointer x6 seeded with the CSR scratch GPA (staged in DATA0 before
  // the FIRST abstract write to x6 -- the seed runs before the GPR loop).
  std::optional<uint32_t> seed_data0;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_gpr(6)
        && ((op.value >> 16) & 1u)) {
      if (bus.ops[i - 2].reg == kData0) seed_data0 = bus.ops[i - 2].value;
      break;
    }
  }
  REQUIRE(seed_data0.has_value());
  CHECK(*seed_data0 == uint32_t(hybrid::csr_scratch_gpa(kScratch) & 0xFFFFFFFFu));
  // (c) NO per-CSR abstract write-COMMAND to a swept CSR -- they rode the sweep.
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    if (!((op.value >> 16) & 1u)) continue;  // writes only
    const uint16_t regno = op.value & 0xFFFFu;
    for (uint16_t a : addrs)
      CHECK(regno != hybrid::regno_csr(a));
  }
}

