// ---- perf experiment: PB csr_sweep restore vs abstract-path restore --------
// Same state, same caps -> the identical transported CSR list; count the DMI
// bus operations and DM commands each path issues. Transaction counts are the
// unit-level proxy for the RTL cycle measurement (each DMI op is one bus
// round-trip; each DM command additionally holds the hart busy while it runs).
TEST_CASE("perf: csr_sweep restore issues fewer DMI ops than per-CSR abstract "
          "writes for the same Andes+M-ext set")
{
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  s.vlenb = 0;  // no V block: isolate the CSR path difference
  uint64_t v = 0xA00000000ULL;
#define X(field, addr, name) s.andes.field = v++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i) s.andes.pmaaddr[i] = v++;
  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)  s.andes.pmacfg[i]  = v++;
#define X(field, addr, name) s.m_ext.field = v++;
  HYBRID_M_EXT_CSR_LIST(X)
#undef X

  std::size_t n_csrs = 0;
  hybrid::for_each_sweep_csr(s, hybrid::AndesCaps::all(),
    [&](std::size_t, uint16_t, const uint64_t&) { ++n_csrs; });

  struct Counts { std::size_t total, xfer_cmds, pb_execs; };
  const auto run = [&](bool sweep) -> Counts {
    RecordingBus bus;
    bus.dmstatus_value   = (1u << 9) | (1u << 17);
    bus.abstractcs_value = 8u << 24;  // progbufsize=8, idle, no cmderr
    hybrid::ResumeDriver d(bus, kScratch);
    d.set_csr_sweep(sweep);
    d.resume(s);
    Counts c{bus.ops.size(), 0, 0};
    for (const auto& op : bus.ops) {
      if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
      if ((op.value >> 17) & 1u) ++c.xfer_cmds;  // Access Register transfer
      else                       ++c.pb_execs;   // Execute Program Buffer
    }
    return c;
  };

  const auto a = run(false);  // per-CSR abstract writes (today's restore)
  const auto b = run(true);   // batched PB ld+csrrw sweep

  MESSAGE("csr set n=" << n_csrs);
  MESSAGE("abstract: DMI ops=" << a.total << " transfer-cmds=" << a.xfer_cmds
          << " pb-execs=" << a.pb_execs);
  MESSAGE("sweep:    DMI ops=" << b.total << " transfer-cmds=" << b.xfer_cmds
          << " pb-execs=" << b.pb_execs);

  CHECK(n_csrs >= 80);  // AndesCaps::all(): 13 Andes + 18 PMA + 51 M-ext
  CHECK(a.pb_execs == 0);
  CHECK(b.pb_execs == (n_csrs + 2) / 3);  // 3 CSRs per exec at progbufsize=8
  CHECK(b.total < a.total);  // the hypothesis, at transaction level
}

