  // fld-sweep repopulates them in ~6 DM round-trips instead of 32 abstract
  // writes. Gate on the FP flag and fpr_scratch_fits (tighter than the GPR
  // gate -- the FPR block sits lower in the page), so a full V page skips
  // staging and the abstract-write fallback runs.
  if ((hybrid_input_state_->flags & HYBRID_FLAG_FP) != 0u
      && hybrid::fpr_scratch_fits(hybrid_input_state_->vlenb))
    hybrid::stage_fpr_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data);
  // NOTE: the RESTORE csr_sweep stays OFF by default. A csrrw to a
  // caps-supported but read-only / WARL-illegal CSR raises cmderr in the
  // Program Buffer, and a batched sweep cannot tolerate a mid-batch fault the
  // way the abstract path's per-CSR clear_cmderr does. Restoring those CSRs is
  // a no-op anyway (can't write a read-only CSR), so restore keeps the
  // abstract-tolerant path until a per-CSR writability model can gate the
  // sweep. The DRAIN sweep IS on (csrr reads never fault for a readable CSR)
  // -- see set_block_store_drain. HYBRID_RESTORE_CSR_SWEEP=1 opts in for
  // measurement: the sweep transports the full caps list (it ignores the LG1
  // baseline), so pair it with --no-reset-baseline for a fair A/B.
  const auto caps = hybrid::andes_caps_from_config();
  const auto env_on = [](const char* name, bool dflt) {
    const char* v = std::getenv(name);
    return v ? v[0] == '1' : dflt;
  };
  const bool restore_csr_sweep = env_on("HYBRID_RESTORE_CSR_SWEEP", false);
  // Measurement opt-outs: fall back to per-register abstract writes so the
  // PB block-load's cycle cost can be A/B-measured on real RTL.
  const bool gpr_block = env_on("HYBRID_RESTORE_GPR_BLOCK", true);
  const bool fpr_block = env_on("HYBRID_RESTORE_FPR_BLOCK", true);
  if (restore_csr_sweep
      && hybrid::csr_scratch_fits(hybrid_input_state_->vlenb))
    hybrid::stage_csr_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data, caps);
  hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
  driver.set_gpr_block_load(gpr_block);
  driver.set_fpr_block_load(fpr_block);
  driver.set_csr_sweep(restore_csr_sweep);
  // LG3: on a capture run the capture drain's V dump sweep clobbered
  // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
  if (baseline)
    driver.set_reset_baseline(*baseline,
                              /*v_cfg_at_reset=*/!baseline_captured);
  std::size_t sweep_csrs = 0;
  hybrid::for_each_sweep_csr(*hybrid_input_state_, caps,
    [&](std::size_t, uint16_t, const uint64_t&) { ++sweep_csrs; });
  const auto resume_t0 = sc_core::sc_time_stamp();
  const auto wall_t0 = std::chrono::steady_clock::now();
  driver.resume(*hybrid_input_state_);
  const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::steady_clock::now() - wall_t0).count();
  const auto resume_cycles = static_cast<uint64_t>(
    (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
  spdlog::info("hybrid: resume={} cycles ({} ms wall), csr-restore path={}, "
               "gpr={}, fpr={}, andes+m-ext csrs={}",
               resume_cycles, wall_ms,
               restore_csr_sweep ? "pb-sweep" : "abstract",
               gpr_block ? "pb-block" : "abstract",
               fpr_block ? "pb-block" : "abstract", sweep_csrs);
  if (baseline)
    spdlog::info("hybrid: liveness gate elided {} register restores",
                 driver.baseline_skip_count());
}

